import { expect, test } from '@playwright/test';

// ---------------------------------------------------------------------------
// A page generated by arizona_static and served as a plain file: no WebSocket,
// only the static client's start(). Its ?local controls still work, entirely in
// the browser, from the event names arizona_static embedded in the page.
// ---------------------------------------------------------------------------

const PAGE = '/static-site/index.html';

/** Open the static page, recording every WebSocket it opens. */
async function open(page) {
    const sockets = [];
    page.on('websocket', (ws) => sockets.push(ws.url()));
    await page.goto(PAGE);
    return sockets;
}

test.describe('static page (no server)', () => {
    test('carries the proven event names', async ({ page }) => {
        await open(page);
        const names = JSON.parse(await page.locator('#arizona-attrs').textContent());
        expect(names).toContain('az-click');
    });

    test('switches tabs in the browser and opens no socket', async ({ page }) => {
        const sockets = await open(page);
        const settings = page.locator('#local_demo .panel-settings');
        await expect(settings).toBeHidden();
        await page.getByRole('button', { name: 'Settings' }).click();
        await expect(settings).toBeVisible();
        await expect(page.locator('#local_demo .panel-home')).toBeHidden();
        expect(sockets).toEqual([]);
    });

    test('opens and closes a dialog bound to ?local', async ({ page }) => {
        await open(page);
        const dialog = page.locator('#local_demo dialog');
        await expect(dialog).not.toHaveAttribute('open');
        await page.getByRole('button', { name: 'Open dialog' }).click();
        await expect(dialog).toHaveAttribute('open', '');
        await expect(page.locator('#local_demo dialog h3 span')).toHaveText(
            'Hello from the client!',
        );
        await page.getByRole('button', { name: 'Close' }).click();
        await expect(dialog).not.toHaveAttribute('open');
    });

    test('updates several ?local slots from one click', async ({ page }) => {
        await open(page);
        await expect(page.locator('#local_demo .name')).toHaveText('Name: Ada Lovelace');
        await page.getByRole('button', { name: 'Rename' }).click();
        await expect(page.locator('#local_demo .name')).toHaveText('Name: Grace Hopper');
    });
});
